"""Optional export profiles: generated bytes, offline plans and fake apply only."""
import contextlib
import io
import json
import subprocess
import sys
import tempfile
import tomllib
import unittest
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import patch

import publish_hf
from head_export_config import FIELDS, read_config, resolve_options
from publication import digest


class HeadExportConfigTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        self.source = self.root / "private source"
        self.source.mkdir()
        manifest = {"release": "internal", "threshold": 0.5, "classifiers": ["hey_hex", "hex"], "heads": {}, "files": {}}
        for key in ["mel", "embedding", *manifest["classifiers"]]:
            data = f"generated test bytes {key}".encode()
            (self.source / f"{key}.onnx").write_bytes(data)
            manifest["files"][key] = {"file": f"{key}.onnx", "sha256": digest(data)}
        for head in manifest["classifiers"]:
            manifest["heads"][head] = {"private": False, "owner_recordings": False}
        (self.source / "manifest.json").write_text(json.dumps(manifest))
        self.directory = self.root / "private settings"
        self.directory.mkdir()
        self.config = self.directory / "head-export.toml"
        self.write_config()
        env = patch.dict("os.environ", {"WAQY_PRIVATE_WORDS": str(self.root / "absent-roster")})
        env.start()
        self.addCleanup(env.stop)

    def write_config(self, extra=""):
        self.config.write_text('[export]\nsource = "../private source"\nname = "public-1"\nheads = ["hey_hex"]\nrepo = "example/wake-heads"\n' + extra)

    def cli(self, *arguments):
        output = io.StringIO()
        with patch.object(sys, "argv", ["publish_hf.py", *arguments]), contextlib.redirect_stdout(output):
            code = publish_hf.main()
        self.assertEqual(code, 0)
        return json.loads(output.getvalue())

    def test_config_only_is_offline_and_private_paths_do_not_enter_plan(self):
        with patch.object(publish_hf, "publish", side_effect=AssertionError("network")):
            result = self.cli("--config", str(self.config))
        self.assertTrue(result["dry_run"])
        self.assertEqual(result["repo"], "example/wake-heads")
        self.assertEqual(result["heads"], ["hey_hex"])
        self.assertNotIn(str(self.root), json.dumps(result))
        self.assertFalse((self.directory / "public-1").exists())

    def test_cli_overrides_source_repo_name_and_heads(self):
        result = self.cli(str(self.source), "--config", str(self.config), "--repo", "another/heads", "--name", "public-2", "--heads", "hex")
        self.assertEqual((result["repo"], result["release"], result["heads"]), ("another/heads", "public-2", ["hex"]))
        args = SimpleNamespace(config=self.config, source=Path("cli-source"), repo=None, name=None, heads=None, metadata=None, consent=None, catalog=None)
        self.assertEqual(resolve_options(args)["source"], Path("cli-source"))

    def test_config_paths_are_relative_to_profile_not_working_directory(self):
        self.write_config('metadata = "records/review.json"\nconsent = "records/consent.json"\ncatalog = "records/catalog.json"\n')
        values = read_config(self.config)
        for key, file in [("metadata", "review.json"), ("consent", "consent.json"), ("catalog", "catalog.json")]:
            self.assertEqual(values[key], (self.directory / "records" / file).resolve())
        self.assertEqual(values["source"].resolve(), self.source.resolve())

    def test_config_cannot_enable_apply_or_hold_credentials(self):
        for extra in ['apply = true\n', 'dry_run = false\n', 'token = "not-a-real-token"\n']:
            with self.subTest(extra=extra):
                self.write_config(extra)
                with self.assertRaisesRegex(ValueError, "unknown head-export settings"):
                    read_config(self.config)
        self.write_config()
        with patch.object(publish_hf, "publish", return_value={"applied": "fake-only"}) as fake:
            self.assertEqual(self.cli("--config", str(self.config), "--apply"), {"applied": "fake-only"})
            self.assertEqual(fake.call_count, 1)
            self.assertEqual(fake.call_args.args[0].manifest["classifiers"], ["hey_hex"])

    def test_unknown_tables_invalid_types_and_head_arrays_fail_closed(self):
        for text in ['[other]\nheads = ["hex"]', '[export]\nheads = "hex"', '[export]\nheads = [1]',
                     '[export]\nheads = []', '[export]\nheads = ["hey_hex,hex"]',
                     '[export]\nheads = ["hex", "hex"]', '[export]\nsource = false',
                     '[export]\nsource = ""', '[export]\nsource = "x"\n[credentials]\ntoken = "x"']:
            with self.subTest(text=text):
                self.config.write_text(text)
                with self.assertRaises((ValueError, TypeError)):
                    read_config(self.config)
        self.config.write_bytes(b"#" * 65_537)
        with self.assertRaisesRegex(ValueError, "64 KiB"):
            read_config(self.config)

    def test_empty_selection_is_not_inferred_and_config_catalog_stays_offline(self):
        self.config.write_text('[export]\nrepo = "example/wake-heads"\n')
        with contextlib.redirect_stderr(io.StringIO()), self.assertRaises(SystemExit) as failure:
            self.cli("--config", str(self.config))
        self.assertEqual(failure.exception.code, 2)
        self.write_config('catalog = "offline.json"\n')
        with patch.object(publish_hf, "publish", side_effect=AssertionError("network")), contextlib.redirect_stderr(io.StringIO()), self.assertRaises(SystemExit):
            self.cli("--config", str(self.config), "--apply")

    def test_just_recipe_handles_private_profile_path_with_spaces(self):
        repo = Path(publish_hf.__file__).resolve().parent.parent
        result = subprocess.run(["just", "publish-heads-config", str(self.config), "--heads", "hex"], cwd=repo, capture_output=True, text=True, check=True)
        plan = json.loads(result.stdout)
        self.assertEqual(plan["heads"], ["hex"])
        self.assertTrue(plan["dry_run"])

    def test_public_example_and_schema_have_no_automatic_selection_or_apply(self):
        directory = Path(publish_hf.__file__).resolve().parent
        schema = json.loads((directory / "head-export.schema.json").read_text())
        self.assertFalse(schema["additionalProperties"])
        self.assertFalse(schema["properties"]["export"]["additionalProperties"])
        self.assertEqual(set(schema["properties"]["export"]["properties"]), FIELDS)
        example = tomllib.loads((directory / "head-export.example.toml").read_text())
        self.assertEqual(example, {"export": {"repo": "byteowlz/waqy"}})


if __name__ == "__main__":
    unittest.main()
